text:
{
 "reason": {
  "es": "内閣《ないかく》は、人事院《じんじいん》という国《くに》の役所《やくしょ》が令和《れいわ》3年《ねん》8月《がつ》10日《とおか》に出《だ》した、給料《きゅうりょう》についての勧《すす》め（勧告《かんこく》）をうけて、この法律《ほうりつ》が必要《ひつよう》だとしている。国《くに》の一般《いっぱん》の公務員《こうむいん》がもらう期末手当《きまつてあて》（いわゆるボーナス）の額《がく》を変《か》えるためだ。",
  "hs": "内閣は、人事院（国の機関の一つ）が令和3年8月10日付けで国会と内閣に出した、職員の給与《きゅうよ》の改定についての勧告《かんこく》（すすめ）をふまえ、一般《いっぱん》職の国家公務員の期末手当（ボーナスにあたるお金）の額を改定する必要があるためとしている。",
  "std": "内閣は、人事院が令和3年8月10日付けで国会と内閣に行った職員の給与の改定に関する勧告をふまえ、一般職の国家公務員の期末手当の額を改定する必要があるためとしている。",
  "univ": "内閣は、人事院の国会及び内閣に対する令和3年8月10日付けの職員の給与の改定に関する勧告に鑑み、一般職の国家公務員の期末手当の額の改定を行う必要があるためとしている。"
 },
 "who": {
  "es": "国《くに》の役所《やくしょ》で働《はたら》く一般《いっぱん》の公務員《こうむいん》。期末手当《きまつてあて》が年《ねん》に0.15か月分《げつぶん》へる（指定職《していしょく》という上《うえ》の立場《たちば》の職員《しょくいん》は0.1か月分《げつぶん》）。",
  "hs": "一般《いっぱん》職の国家公務員。期末手当が年間0.15月分（指定職の職員は年間0.1月分）引き下げられる。",
  "std": "一般職の国家公務員（期末手当が年間0.15月分、指定職職員は年間0.1月分引き下げられる）。",
  "univ": "一般職の国家公務員（期末手当の支給割合が年間0.15月分、指定職職員については年間0.1月分引き下げられる）。"
 },
 "committee": {
  "es": "衆議院《しゅうぎいん》では、内閣委員会《ないかくいいんかい》が、ほかの2つの法律案《ほうりつあん》といっしょに調《しら》べた。3月《がつ》4日《よっか》に大臣《だいじん》から説明《せつめい》を聞《き》き、9日《ここのか》に質問《しつもん》と話《はな》し合《あ》いをして、賛成《さんせい》が多《おお》く、そのまま認《みと》めると決《き》めた。参議院《さんぎいん》でも、内閣委員会《ないかくいいんかい》が3つの法律案《ほうりつあん》をいっしょに調《しら》べた。今回《こんかい》の給料《きゅうりょう》の決《き》め方《かた》や、国《くに》の公務員《こうむいん》が育児休業《いくじきゅうぎょう》を取《と》りやすい職場《しょくば》づくり、人《ひと》を集《あつ》める工夫《くふう》などについて質問《しつもん》があった。日本共産党《にほんきょうさんとう》が反対《はんたい》の意見《いけん》を述《の》べ、賛成《さんせい》が多《おお》く、そのまま認《みと》めると決《き》めた。",
  "hs": "衆議院では、内閣委員会がほかの2つの法律案と一緒《いっしょ》に審査《しんさ》した。3月4日に二之湯《にのゆ》国務大臣から趣旨《しゅし》（ねらい）の説明を聞き、9日に質疑と討論をして、賛成多数で原案のとおり可決すべきと決めた。参議院でも内閣委員会が3つの法律案をまとめて審査《しんさ》した。人事院の勧告《かんこく》をふまえた今回の給与《きゅうよ》改定のあり方、国家公務員が育児休業を取りやすい環境《かんきょう》づくり、国家公務員の人材確保策などについて質疑があった。討論では日本共産党が反対の意見を述べ、採決の結果、多数で原案どおり可決すべきと決めた。",
  "std": "衆議院では内閣委員会が、特別職の給与法改正案と国家公務員育児休業法等改正案と一括して審査した。3月4日に二之湯国務大臣から趣旨説明を聴取し、9日に質疑・討論を行い、賛成多数で原案のとおり可決すべきものと決めた。参議院でも内閣委員会が3法律案を一括して審査し、人事院勧告を踏まえた今回の給与改定の在り方、国家公務員が育児休業を取得しやすい環境整備、国家公務員の人材確保策などについて質疑が行われた。討論では日本共産党が反対の意見を述べ、採決の結果、多数で原案どおり可決すべきものと決定した。",
  "univ": "衆議院では、3月3日に内閣委員会に付託され、特別職の職員の給与に関する法律の一部を改正する法律案及び国家公務員の育児休業等に関する法律等の一部を改正する法律案とともに審査された。4日に二之湯国務大臣から趣旨の説明を聴取し、9日に質疑、討論を行った後、採決の結果、賛成多数をもって原案のとおり可決すべきものと決した。参議院では、内閣委員会において3法律案を一括して議題とし、人事院勧告を踏まえた今回の給与改定の在り方、国家公務員が育児休業を取得しやすい環境整備、国家公務員の人材確保策等について質疑が行われた。討論では日本共産党の委員より反対の意見が述べられ、採決の結果、多数をもって原案どおり可決すべきものと決定した。"
 },
 "views": [
  {
   "side": "反対",
   "group": "日本共産党",
   "where": "衆議院 内閣委員会、参議院 内閣委員会",
   "text": {
    "es": "日本共産党《にほんきょうさんとう》は、反対《はんたい》した。経済《けいざい》が悪《わる》くなっている中《なか》で、民間《みんかん》に合《あ》わせることだけを理由《りゆう》にボーナスを下《さ》げるべきではないと述《の》べた。定年《ていねん》のあと、また働《はたら》く人《ひと》の手当《てあて》まで減《へ》らすのは認《みと》められないとした。約《やく》770万人《まんにん》の働《はたら》く人《ひと》に影響《えいきょう》し、買《か》い物《もの》が減《へ》ることも理由《りゆう》にあげた。",
    "hs": "日本共産党は、経済の状況《じょうきょう》が悪くなる中で、人事院が民間に合わせることだけを理由に期末手当を下げるのは、労働基本権の制約の代わりとなる役割を果たしていないと述べた。定年退職後に再任用される職員の手当からも減額するのは認められないとした。約770万人の労働者に影響《えいきょう》し、消費を冷え込《こ》ませることも理由に反対した。",
    "std": "日本共産党は、経済状況が悪化する中、民間準拠だけを理由に期末手当を引き下げるのは労働基本権制約の代償措置の役割を果たしていないと述べた。定年退職後に再任用される職員の手当からも減額調整を行うことは認められないとし、約770万人の労働者に影響して消費を冷え込ませることも理由に反対した。",
    "univ": "日本共産党は、新型コロナウイルス感染症や物価高騰等で経済状況が悪化する下、人事院が民間準拠だけを理由に期末手当を引き下げる勧告を行ったことは、国家公務員の労働基本権制約に対する代償措置としての役割を果たしていないと述べた。また、減額調整の特例を今年度末で定年退職し4月から再任用される職員の手当からも行うことは認められないとし、給与引下げが約770万人の労働者に影響を与え、民間事業者にも波及して国民の消費を冷え込ませることを理由に反対した。"
   }
  },
  {
   "side": "反対",
   "group": "れいわ新選組",
   "where": "衆議院 内閣委員会",
   "text": {
    "es": "れいわ新選組《しんせんぐみ》は、反対《はんたい》した。政府《せいふ》は、給料《きゅうりょう》を上《あ》げて経済《けいざい》をよくするという方針《ほうしん》を出《だ》しているのに、公務員《こうむいん》の給料《きゅうりょう》を下《さ》げるのは逆《ぎゃく》だと述《の》べた。公務員《こうむいん》のお金《かね》をけずる流《なが》れが、民間《みんかん》の給料《きゅうりょう》や、医療《いりょう》・介護《かいご》などのサービスもけずってきたとした。",
    "hs": "れいわ新選組は、政府が「骨太《ほねぶと》の方針2021」でかかげた、賃上げを通じた経済の底上げとは逆に、公務員の賃金を下げる法律案だと述べた。公務員の人件費を減らす流れが、民間労働者の給与《きゅうよ》や、公的な医療《いりょう》・保健所・介護《かいご》などの福祉《ふくし》サービスの削減《さくげん》につながってきたとして反対した。",
    "std": "れいわ新選組は、政府が「骨太の方針2021」でうたった賃上げを通じた経済の底上げとは逆に、使用者の立場にある公務員の賃金を下げる法案だと述べた。公務員の人件費削減の流れが、民間労働者の給与や公的な医療・保健所・介護などの福祉サービスの削減につながってきたとし、景気をよくするため政策の転換を求めて反対した。",
    "univ": "れいわ新選組は、政府が骨太の方針2021においてうたった賃上げを通じた経済の底上げを行うべきであり、自らが使用者の位置にある公務員の賃金について賃下げ法案を提出するのは逆を行く行為だと述べた。また、公務員の人件費削減を通じて民間労働者の給与や、公的な医療、保健所、介護などの住民に必要な福祉サービスが切られてきたとし、こうした政策を脱却して景気をよくするときだとして反対した。"
   }
  }
 ],
